-- Dansk portion 10 del 3/3: 166 MC-spørgsmål på sværhedsskalaen 1-10.000, niveau 6600-9994.
-- Del af de 5.000 nye danskopgaver. Skrevet fra bunden til dansk folkeskole, 3.-9. klasse.
-- Genereret af tools/questions/build-danish-5000.mjs; ret i tools/questions/fixtures/danish-5000/, ikke her.
-- Kræver migration A (20261020120000_difficulty_scale_a): kolonnen questions.difficulty_level.
--
-- Niveau: hver opgave har et eksplicit difficulty_level (forfatterens skøn, ikke en måling).
-- target_grade/difficulty_band er afledt baglæns af niveauet (cellen i §4.1).
--
-- INAKTIV VED INDSÆTTELSEN: alle rækker får is_active=false og metadata.level_batch='danish10'.
-- Aktivering er en SEPARAT migration efter dokumenteret stikprøvekontrol og særskilt ejergodkendelse.
-- Må KUN anvendes via apply_migration med særskilt ejer-autorisation (D-110).

INSERT INTO public.questions (content, answer_format, answer_type, metadata, type, difficulty, question_type, is_active, learning_objective, target_grade, difficulty_band, difficulty_level)
SELECT
  jsonb_build_object('question', e->>'q', 'options', e->'o', 'correct', e->>'a',
                     'accepted_answers', jsonb_build_array(e->>'a'), 'review_text', e->>'r'),
  'mc', 'short',
  jsonb_build_object('concepts', jsonb_build_array(m.concept), 'cognitive_skill', m.skill,
                     'difficulty_type', m.dtype, 'misconception_type', m.mis,
                     'challenge_role', e->>'role', 'insight_type', e->>'insight',
                     'practice_variant', e->>'variant',
                     'level_batch', 'danish10', 'domain', 'danish'),
  'mc_single', (e->>'b')::int, 'auto', false, 'danish', (e->>'g')::int,
  (e->>'b')::int, (e->>'l')::int
FROM jsonb_array_elements($$[
{"l":6600,"g":7,"b":4,"role":"challenge","insight":"reframing","k":"f","variant":"authored","q":"I hvilket nuværende land lå Karen Blixens kaffefarm?","o":["Egypten","Indien","Kenya","Brasilien"],"a":"Kenya","r":"Karen Blixen drev en kaffefarm i det nuværende Kenya. Det skrev hun om i 'Den afrikanske Farm'."},
{"l":6620,"g":7,"b":4,"role":"challenge","insight":"reframing","k":"g","variant":"authored","q":"Hvor mange hovedsætninger er der i: 'Mads læste, og Ida tegnede.'?","o":["én","tre","fire","to"],"a":"to","r":"Begge dele kan stå alene som sætninger, og 'og' binder dem sammen. Der er altså to sideordnede hovedsætninger."},
{"l":6641,"g":7,"b":4,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"'Hun tilkendegav, at hun var uenig.' Hvad gjorde hun?","o":["viste det tydeligt","holdt det for sig selv","ændrede mening bagefter","spurgte de andre til råds"],"a":"viste det tydeligt","r":"At tilkendegive er at give noget til kende, altså at lade andre vide, hvad man mener."},
{"l":6663,"g":7,"b":4,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Sæt det rigtige ord ind: 'Forskerne var ___ over for de nye tal.'","o":["skeptisk","skeptiske","skepsis","skeptiker"],"a":"skeptiske","r":"Grundleddet 'forskerne' står i flertal, så tillægsordet skal også stå i flertal med -e. 'Skepsis' og 'skeptiker' er navneord."},
{"l":6684,"g":7,"b":4,"role":"challenge","insight":"reframing","k":"l","variant":"authored","q":"Læs: 'Skolen indfører et forsøg med mødetid klokken 9 for 8. klasse. Mange elever jubler, mens nogle forældre frygter, at de ikke kan nå på arbejde. Skolen vil vurdere ordningen efter tre måneder.' Hvad kan man slutte om forsøget?","o":["Forældrene har stemt forsøget igennem","Eleverne får længere tid til lektier","Det er ikke sikkert, at ordningen fortsætter","Forsøget gælder alle skolens klassetrin"],"a":"Det er ikke sikkert, at ordningen fortsætter","r":"Når der står 'forsøg' og 'vurdere efter tre måneder', er beslutningen ikke endelig. Det er en slutning ud fra ordvalget."},
{"l":6700,"g":7,"b":4,"role":"challenge","insight":"reframing","k":"l","variant":"authored","q":"Læs: 'Vi kalder det skærmtid, som om alt foran en skærm var det samme. Men tre timer med en strikkevideo og tre timer med tomt scrolleri er ikke det samme.' Hvad er skribentens kritik af ordet?","o":["Det får skærme til at lyde mere farlige, end de er","Det er for langt og burde erstattes af et kortere","Det bruges mest af voksne og sjældent af børn","Det skærer vidt forskelligt indhold over én kam"],"a":"Det skærer vidt forskelligt indhold over én kam","r":"Skribenten siger, at tiden alene ikke fortæller noget. Det afgørende er, hvad man laver, og det dækker ordet over."},
{"l":6720,"g":7,"b":4,"role":"challenge","insight":"reframing","k":"t","variant":"authored","q":"Hvilken sætning er tegnsat rigtigt om øen i Østersøen?","o":["Bornholm, som ligger i Østersøen, er kendt for klipper.","Bornholm, som ligger i Østersøen er kendt for klipper.","Bornholm som ligger, i Østersøen er kendt for klipper.","Bornholm som ligger i, Østersøen er kendt for klipper."],"a":"Bornholm, som ligger i Østersøen, er kendt for klipper.","r":"Ledsætningen 'som ligger i Østersøen' er indskudt og skal afsluttes med komma efter 'Østersøen'."},
{"l":6741,"g":7,"b":4,"role":"challenge","insight":"reframing","k":"g","variant":"authored","q":"Hvilket stedord skal stå: 'Elias så ___ selv i spejlet.'?","o":["ham","sig","sin","hans"],"a":"sig","r":"Når stedordet viser tilbage til grundleddet Elias, skal det være det tilbagevisende stedord 'sig'."},
{"l":6761,"g":7,"b":4,"role":"challenge","insight":"reframing","k":"l","variant":"authored","q":"Læs: 'Elevrådsformanden sluttede sin tale: Vi vil gerne takke ledelsen for at lytte. Og vi ser frem til, at den også begynder at svare.' Hvilken funktion har den sidste sætning?","o":["Den er en ren og ærlig tak for god behandling","Den er et forslag om en ny mødetid","Den er en høflig stikpille til ledelsen","Den er et løfte om mere samarbejde"],"a":"Den er en høflig stikpille til ledelsen","r":"Den ser pæn ud, men fortæller, at ledelsen hidtil ikke har svaret. Takken bliver dermed til kritik."},
{"l":6783,"g":7,"b":4,"role":"challenge","insight":"reframing","k":"l","variant":"authored","q":"Læs: 'Vores skole er den bedste i kommunen, for ingen anden skole er lige så god.' Hvad er der galt med begrundelsen?","o":["Den nævner kun skolerne i én kommune","Den er for kort til at være et rigtigt argument","Den bygger på for mange forskellige tal","Den gentager bare påstanden med andre ord"],"a":"Den gentager bare påstanden med andre ord","r":"'Den bedste' og 'ingen er lige så god' siger det samme. Det kaldes en cirkelslutning, for begrundelsen tilføjer intet nyt."},
{"l":6800,"g":7,"b":4,"role":"challenge","insight":"reframing","k":"l","variant":"authored","q":"Læs: 'Der stod Jensen og Søn over butikken, men sønnen havde ingen set i tyve år. Hvert forår malede den gamle Jensen skiltet op, begge navne.' Hvad fortæller hans handling?","o":["At han ikke vil give slip på sønnen","At sønnen er på vej hjem til butikken","At han er utilfreds med skiltets farve","At han har glemt, at han har en søn"],"a":"At han ikke vil give slip på sønnen","r":"At male 'Søn' op igen er et stille håb eller et savn. Skiltet holder liv i det, der ikke længere er."},
{"l":6816,"g":7,"b":4,"role":"challenge","insight":"reframing","k":"l","variant":"authored","q":"Læs: 'Kommunen vil bygge et nyt kulturhus for 90 millioner. Samtidig må skolerne spare på vikarer. Men et lysanlæg er vel også vigtigere end at have en voksen i klassen.' Hvordan skal sidste sætning forstås?","o":["Som en ærlig ros af det nye kulturhus","Som ironi, for skribenten mener det modsatte","Som et forslag om at købe et nyt lysanlæg","Som en oplysning om kommunens vikarer"],"a":"Som ironi, for skribenten mener det modsatte","r":"Ordene 'vel også' sætter et lysanlæg over en voksen i klassen på en måde, der lyder absurd. Skribenten kritiserer prioriteringen ved at lade, som om den er rimelig."},
{"l":6838,"g":7,"b":4,"role":"challenge","insight":"reframing","k":"s","variant":"authored","q":"Hvilket ord er rigtigt? 'Hun fik en ___ for sin ømme ryg.'","o":["masage","massasje","massage","masasse"],"a":"massage","r":"Ordet kommer fra fransk, har dobbelt-s og ender på -age."},
{"l":6860,"g":7,"b":5,"role":"challenge","insight":"reframing","k":"t","variant":"authored","q":"Der står hverken 'som' eller 'der' i sætningen. Efter hvilket ord skal der alligevel komma: 'Den film vi så i går var uhyggelig.'?","o":["så","var","uhyggelig","går"],"a":"går","r":"'vi så i går' er en ledsætning, hvor 'som' er sparet væk. Den skal stadig afsluttes med komma."},
{"l":6880,"g":7,"b":5,"role":"challenge","insight":"reframing","k":"t","variant":"authored","q":"Hvilken af disse er indirekte tale?","o":["Selma sagde, at hun ville komme senere","Selma sagde: »Jeg kommer senere«","»Kommer du senere?« spurgte Selma","Selma råbte: »Vi ses senere!«"],"a":"Selma sagde, at hun ville komme senere","r":"I indirekte tale genfortæller man, hvad en person sagde, og så skal der ikke anførselstegn."},
{"l":6898,"g":7,"b":5,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Hvilket udsagnsord i navneform hører til navneordet 'definition'?","o":["definitiv","definere","definerbar","definitioner"],"a":"definere","r":"At definere er at fastlægge, hvad noget betyder. 'Definitiv' er et tillægsord og betyder endelig."},
{"l":6915,"g":7,"b":5,"role":"challenge","insight":"reframing","k":"g","variant":"authored","q":"Hvad kaldes den lange tillægsform 'smilende' på latin?","o":["perfektum participium","præteritum","præsens participium","infinitiv"],"a":"præsens participium","r":"Lang tillægsform på -ende hedder præsens participium. Præteritum er datid."},
{"l":6937,"g":7,"b":5,"role":"challenge","insight":"reframing","k":"g","variant":"authored","q":"Hvilken form passer: 'De ___ nøgler lå på skolens kontor.'?","o":["fundet","finde","finder","fundne"],"a":"fundne","r":"Foran et navneord i bestemt form eller flertal bøjes kort tillægsform som tillægsord. Af 'fundet' bliver det 'fundne'."},
{"l":6959,"g":7,"b":5,"role":"challenge","insight":"reframing","k":"g","variant":"authored","q":"Hvilken sætning om sne har en at-sætning som ledsætning?","o":["Jeg tror, at det bliver sne.","Jeg så den sne, som faldt.","Jeg frøs, da det sneede.","Jeg spurgte, om det sneede."],"a":"Jeg tror, at det bliver sne.","r":"En at-sætning begynder med 'at' og udtrykker her, hvad jeg tror. De andre er en relativsætning, en adverbialsætning og en spørgende ledsætning."},
{"l":6980,"g":7,"b":5,"role":"challenge","insight":"reframing","k":"t","variant":"authored","q":"Efter hvilket ord skal der komma: 'Hvis det sner i weekenden så tager vi kælkene frem.'?","o":["sner","weekenden","så","tager"],"a":"weekenden","r":"Ledsætningen slutter efter 'weekenden'. Kommaet står derfor foran 'så' og ikke efter det."},
{"l":7000,"g":7,"b":5,"role":"challenge","insight":"reframing","k":"t","variant":"authored","q":"Hvor skal kommaet stå: 'Hvad Zainab sagde hørte jeg ikke.'?","o":["efter Zainab","efter hørte","efter sagde","efter jeg"],"a":"efter sagde","r":"'Hvad Zainab sagde' er en ledsætning, der står først og er genstand for 'hørte'."},
{"l":7014,"g":7,"b":5,"role":"challenge","insight":"reframing","k":"l","variant":"authored","q":"Læs: 'Når vi får en ny idrætshal, holder 7.c endelig op med at tabe.' Hvad er forudsætningen for påstanden?","o":["At 7.c allerede vinder de fleste af kampene","At den nye idrætshal bliver meget dyr at bygge","At andre klasser ikke må bruge den nye hal","At hallen er årsag til klassens nederlag"],"a":"At hallen er årsag til klassens nederlag","r":"Påstanden giver kun mening, hvis den gamle hal er grunden til, at de taber. Det tages for givet uden at blive begrundet."},
{"l":7036,"g":7,"b":5,"role":"challenge","insight":"reframing","k":"g","variant":"authored","q":"Hvordan skal sætningen fortsætte: 'Det er koldt, derfor …'?","o":["tager jeg jakke på","jeg tager jakke på","jeg jakke tager på","at jeg tager jakke på"],"a":"tager jeg jakke på","r":"'Derfor' er et biord, ikke et bindeord, og det fylder første plads. Så skal verbet stå lige efter, og grundleddet kommer bagefter."},
{"l":7058,"g":7,"b":5,"role":"challenge","insight":"reframing","k":"l","variant":"authored","q":"Læs: 'Et kort over byen viser cykeluheld som røde prikker. Der er flest prikker på Storegade, som også er den vej, hvor flest mennesker cykler.' Hvad kan kortet ikke fortælle?","o":["Hvor i byen der samlet set er sket flest cykeluheld","Om Storegade er farligst for den enkelte cyklist","Om der er sket uheld på Storegade","Hvor uheldene er placeret på byens veje"],"a":"Om Storegade er farligst for den enkelte cyklist","r":"Mange cyklister giver mange uheld, også hvis risikoen er lav. For at vurdere faren skal uheldene sammenholdes med antal cyklister."},
{"l":7080,"g":7,"b":5,"role":"challenge","insight":"reframing","k":"g","variant":"authored","q":"Hvilken form passer: 'En af pigerne på holdet var ___ i sidste uge.'?","o":["syge","sygt","syg","sygen"],"a":"syg","r":"Grundleddet er 'en', altså ental fælleskøn, selv om 'pigerne' står i flertal lige efter. Derfor skal der stå 'syg'."},
{"l":7101,"g":7,"b":5,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Læreren fandt en 'salomonisk' løsning på striden. Hvordan var løsningen?","o":["hård og streng over for begge parter","dyr og besværlig for begge parter","uklar og svær at forstå for begge parter","klog og retfærdig over for begge parter"],"a":"klog og retfærdig over for begge parter","r":"Ordet kommer af kong Salomon, som i Det Gamle Testamente er kendt for sin store visdom."},
{"l":7123,"g":7,"b":5,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Museet blev støttet af en 'mæcen'. Hvem er det?","o":["en rig person, der støtter kunsten","en kunstner, der laver udstillinger","en ansat, der passer på kunstværkerne","en fagperson, der vurderer gamle malerier"],"a":"en rig person, der støtter kunsten","r":"Ordet kommer af romeren Maecenas, som på kejser Augustus' tid støttede digtere som Vergil og Horats."},
{"l":7146,"g":8,"b":1,"role":"challenge","insight":"reframing","k":"f","variant":"authored","q":"Hvilke træk er typiske for romantikken?","o":["Samfundskritik og fakta","Fantasi, natur og længsel","Fri vers og brudstykker","Fornuft og vittige komedier"],"a":"Fantasi, natur og længsel","r":"Romantikerne søgte det store og det ukendte og satte følelser og natur højt. Samfundskritik hører til det moderne gennembrud."},
{"l":7168,"g":8,"b":1,"role":"challenge","insight":"reframing","k":"g","variant":"authored","q":"Hvilket led er 'Det' i: 'Det regner hele dagen.'?","o":["genstandsled","hensynsled","formelt grundled","omsagnsled"],"a":"formelt grundled","r":"En dansk sætning skal have et grundled. 'Det' står her kun for at fylde pladsen og betyder ikke noget bestemt."},
{"l":7190,"g":8,"b":1,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Hvad kendetegner en 'nuanceret' holdning?","o":["den holder sig til én simpel sandhed","den bliver sagt meget højt","den deles af næsten alle","den ser sagen fra flere sider"],"a":"den ser sagen fra flere sider","r":"Nuancer er små forskelle. En nuanceret holdning tager højde for, at en sag sjældent kun har én side."},
{"l":7205,"g":8,"b":1,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Væksten i byen er 'stagneret'. Hvad betyder det?","o":["den er gået i stå","den er steget kraftigt","den er blevet målt","den er kommet som en overraskelse"],"a":"den er gået i stå","r":"Stagnere kommer af latin 'stagnum', som betyder stillestående vand. Noget, der stagnerer, udvikler sig altså ikke længere."},
{"l":7226,"g":8,"b":1,"role":"challenge","insight":"reframing","k":"l","variant":"authored","q":"Læs: 'Modstanderne af fælles skolekørsel vil åbenbart have, at børn skal gå ti kilometer i snestorm.' Hvad gør skribenten med modstandernes synspunkt?","o":["Gengiver det præcist, som modstanderne selv siger","Forvrænger det til noget, der er nemt at afvise","Overvejer det og giver dem ret til sidst i teksten","Fremhæver det som det stærkeste argument i debatten"],"a":"Forvrænger det til noget, der er nemt at afvise","r":"Det kaldes et stråmandsargument. I stedet for at svare på den reelle kritik gør skribenten modparten mere ekstrem, end den er."},
{"l":7245,"g":8,"b":1,"role":"challenge","insight":"reframing","k":"g","variant":"authored","q":"Hvor mange ledsætninger er der i: 'Jeg tror, at Maja kommer, når hun har fri.'?","o":["én","tre","to","fire"],"a":"to","r":"'At Maja kommer' og 'når hun har fri' er begge ledsætninger. Den sidste hører til den første, og kun 'Jeg tror' er hovedsætning."},
{"l":7267,"g":8,"b":1,"role":"challenge","insight":"reframing","k":"g","variant":"authored","q":"Hvilket sætningsled er ledsætningen i: 'Vi spiller videre, når regnen stopper.'?","o":["grundled","genstandsled","omsagnsled","adverbialled"],"a":"adverbialled","r":"Ledsætningen siger, hvornår vi spiller videre. Den er et led, der angiver tid, og derfor kaldes den en adverbialsætning."},
{"l":7289,"g":8,"b":1,"role":"challenge","insight":"reframing","k":"g","variant":"authored","q":"Hvilken type stedord er 'Ingen' i: 'Ingen havde set katten den dag.'?","o":["ubestemt stedord","personligt stedord","ejestedord","påpegende stedord"],"a":"ubestemt stedord","r":"'Ingen' peger ikke på en bestemt person. Det samme gælder 'nogen', 'alle' og 'enhver', som også er ubestemte stedord."},
{"l":7309,"g":8,"b":1,"role":"challenge","insight":"reframing","k":"s","variant":"authored","q":"Hvad skal der stå? 'Efter maratonløbet var hun helt ___.'","o":["udmatet","udmattet","udmatted","udmadet"],"a":"udmattet","r":"Ordet kommer af 'mat' og får dobbelt-t, når endelsen -et kommer på."},
{"l":7328,"g":8,"b":1,"role":"challenge","insight":"reframing","k":"f","variant":"authored","q":"Læs: 'De næste tre år gik stille. Mads flyttede to gange, fik nyt arbejde og begyndte at spille skak.' Hvordan fremstilles tiden her?","o":["Som en scene med replikker","Som en indre monolog i nutid","Som et referat med store spring","Som en grundig naturbeskrivelse"],"a":"Som et referat med store spring","r":"Tre år fortælles på to linjer. I et referat springer fortælleren hurtigt hen over tiden."},
{"l":7348,"g":8,"b":1,"role":"challenge","insight":"reframing","k":"t","variant":"authored","q":"Hvorfor skal der ikke komma i 'At læse hver dag styrker ordforrådet.'?","o":["Fordi sætningen er kortere end ti ord i alt","Fordi 'at' aldrig må stå først i en sætning","Fordi 'dag' er en tidsangivelse i sætningen","Fordi der ikke er nogen ledsætning i sætningen"],"a":"Fordi der ikke er nogen ledsætning i sætningen","r":"'At læse' er navneform og altså ikke en ledsætning, så der er ingen sætningsgrænse at markere."},
{"l":7370,"g":8,"b":1,"role":"challenge","insight":"reframing","k":"f","variant":"authored","q":"Hvad er en upålidelig fortæller?","o":["En fortæller, hvis version læseren har grund til at tvivle på","En fortæller, der kender alle personers inderste tanker","En fortæller, der kun beskriver det, et kamera kan se","En fortæller, der skifter mellem forskellige personer"],"a":"En fortæller, hvis version læseren har grund til at tvivle på","r":"Fortælleren lyver, misforstår eller pynter på sagerne. Læseren må derfor læse kritisk og selv gennemskue, hvad der er sket."},
{"l":7392,"g":8,"b":1,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Hvilket ord bruger man om at flytte ud af sit hjemland for at bo i et andet land?","o":["immigrere","emigrere","integrere","eskalere"],"a":"emigrere","r":"E- betyder 'ud', så man emigrerer ud af et land. Forleddet i 'immigrere' betyder 'ind', så man immigrerer ind i et land."},
{"l":7407,"g":8,"b":1,"role":"challenge","insight":"reframing","k":"s","variant":"authored","q":"Hvad er stavet rigtigt? 'I ___ lærte vi om floder, bjerge og klimazoner.'","o":["geographi","giografi","geografi","geograffi"],"a":"geografi","r":"Ordet kommer fra græsk. Det skrives med f på dansk, ikke ph."},
{"l":7424,"g":8,"b":1,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Hvad betyder det at 'rende panden mod en mur'?","o":["at få en bule efter en lille ulykke i idrætshallen","at blive vred over en beslutning fra ledelsen","at gå hurtigt hjem efter en lang dag i skolen","at møde en modstand, man ikke kan komme igennem"],"a":"at møde en modstand, man ikke kan komme igennem","r":"En mur giver ikke efter, uanset hvor mange gange man prøver. Udtrykket bruges om nytteløse forsøg på at ændre noget."},
{"l":7446,"g":8,"b":2,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Hvad fortæller efterleddet '-logi' om et fag som 'geologi' eller 'psykologi'?","o":["at det er læren om noget","at det er frygten for noget","at det er styret af noget","at det er skrevet om noget"],"a":"at det er læren om noget","r":"'-logi' kommer af det græske 'logos', som blandt andet betyder ord og lære. Geologi er læren om jorden, og psykologi er læren om sjælelivet."},
{"l":7465,"g":8,"b":2,"role":"challenge","insight":"reframing","k":"g","variant":"authored","q":"Hvilket led er 'Bølle' i: 'De kaldte hunden Bølle.'?","o":["omsagnsled til grundleddet","omsagnsled til genstandsleddet","hensynsled til genstandsleddet","grundled i en ledsætning"],"a":"omsagnsled til genstandsleddet","r":"'Bølle' siger noget om hunden, som er genstandsled. Hunden og Bølle er det samme, og derfor er det et omsagnsled."},
{"l":7488,"g":8,"b":2,"role":"challenge","insight":"reframing","k":"f","variant":"authored","q":"Hvor mange verslinjer har en klassisk sonet?","o":["otte","tolv","fjorten","tyve"],"a":"fjorten","r":"En klassisk sonet har 14 verslinjer. Den er en fast digtform, der stammer fra Italien."},
{"l":7502,"g":8,"b":2,"role":"challenge","insight":"reframing","k":"f","variant":"authored","q":"Hvad er et haiku?","o":["En lang fortælling om japanske krigere","Et rimet digt med fjorten verslinjer","En gammel dansk sang med omkvæd","Et kort japansk digt på tre linjer"],"a":"Et kort japansk digt på tre linjer","r":"Haiku er en japansk digtform på tre linjer. Digtet fanger ofte et lille øjeblik i naturen."},
{"l":7521,"g":8,"b":2,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Hvad er et 'incitament'?","o":["noget, der motiverer en til at handle","noget, der forbyder en at handle","noget, man bruger til at beregne skat","noget, man skriver i en årsrapport"],"a":"noget, der motiverer en til at handle","r":"Et incitament er en tilskyndelse, for eksempel en belønning, der får en til at gøre noget. Økonomiske incitamenter nævnes tit i avisen."},
{"l":7543,"g":8,"b":2,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Klassen spørger 200 elever og opgør svarene i procent. Hvilken slags undersøgelse er det?","o":["kvalitativ","kvantitativ","spekulativ","dekorativ"],"a":"kvantitativ","r":"Kvantitativ handler om mængde: tal, som kan tælles og sammenlignes. En kvalitativ undersøgelse går i dybden med få personer, for eksempel gennem interview."},
{"l":7561,"g":8,"b":2,"role":"challenge","insight":"reframing","k":"s","variant":"authored","q":"Sæt ind: 'Han havde dårlig ___, efter at han havde løjet.'","o":["samvitighed","samvittihed","samvittighed","samvittiged"],"a":"samvittighed","r":"Ordet har dobbelt-t, og det stumme g foran -hed skal med."},
{"l":7586,"g":8,"b":2,"role":"challenge","insight":"reframing","k":"g","variant":"authored","q":"Hvilket af disse bindeord kan ikke indlede en ledsætning?","o":["fordi","hvis","når","men"],"a":"men","r":"'Men' er sideordnende og binder ligestillede sætninger sammen. De tre andre er underordnende og indleder ledsætninger."},
{"l":7603,"g":8,"b":2,"role":"challenge","insight":"reframing","k":"s","variant":"authored","q":"Hvad står der rigtigt? 'Efter sejren havde holdet masser af ___.'","o":["selvtillid","selvtilid","selvtillit","seltillid"],"a":"selvtillid","r":"Ordet består af 'selv' og 'tillid'. Derfor er der dobbelt-l, og v'et må ikke glemmes."},
{"l":7626,"g":8,"b":2,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Hvad betyder forleddet 'a-' i 'asymmetrisk' og 'apolitisk'?","o":["med","uden","imod","efter"],"a":"uden","r":"Græsk 'a-' betegner, at noget mangler. Noget asymmetrisk er uden symmetri, og den apolitiske tager ikke del i politik."},
{"l":7645,"g":8,"b":2,"role":"challenge","insight":"reframing","k":"s","variant":"authored","q":"Hvad er stavet rigtigt? 'Jeg glemte ___ min madpakke, så jeg måtte låne penge.'","o":["uheldivis","uhældigvis","uheldigvis","uheldigvist"],"a":"uheldigvis","r":"Ordet kommer af 'uheldig' og endelsen -vis. Det stumme g skal med, og der er intet t til sidst."},
{"l":7670,"g":8,"b":2,"role":"challenge","insight":"reframing","k":"f","variant":"authored","q":"Hvilken roman er skrevet af J.P. Jacobsen?","o":["Lykke-Per","Tine","Stuk","Niels Lyhne"],"a":"Niels Lyhne","r":"J.P. Jacobsen udgav 'Niels Lyhne' i 1880. 'Lykke-Per' er af Pontoppidan, og 'Tine' og 'Stuk' er af Bang."},
{"l":7687,"g":8,"b":2,"role":"challenge","insight":"reframing","k":"s","variant":"authored","q":"Hvad skal der stå? 'Turen er billig, og ___ er vejret godt.'","o":["desuden","dessuden","desudden","desude"],"a":"desuden","r":"Ordet består af 'des' og 'uden'. Det skrives i ét, med ét s."},
{"l":7707,"g":8,"b":2,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Hvad er opfordringen, når man siger til nogen, at de skal 'feje for egen dør'?","o":["at de skal holde deres indkørsel pæn","at de først skal se på deres egne fejl","at de skal gøre rent, før gæster kommer","at de skal gå hjem og tage en pause"],"a":"at de først skal se på deres egne fejl","r":"Udtrykket bruges til en, der kritiserer andre: Før du gør det, må du se på dine egne fejl."},
{"l":7727,"g":8,"b":3,"role":"challenge","insight":"reframing","k":"l","variant":"authored","q":"Læs: 'Et barn lærer at tale uden undervisning, blot ved at høre andre tale. At læse lærer man derimod sjældent af sig selv. Skrift er en opfindelse, som hver ny generation må øve sig på.' Hvilken forskel forklarer teksten?","o":["Tale kræver lærere, mens læsning kommer af sig selv","Skrift er ældre end tale og derfor sværere at lære","Tale tilegnes af sig selv, læsning skal læres bevidst","Børn lærer begge dele ved blot at høre andre gøre det"],"a":"Tale tilegnes af sig selv, læsning skal læres bevidst","r":"Ordet 'derimod' viser kontrasten. Læsning kræver træning, fordi den ikke kommer af sig selv som talen."},
{"l":7747,"g":8,"b":3,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"En taler overbeviser sit publikum med tal og saglige begrundelser. Hvilken appelform bruger taleren?","o":["etos","patos","kairos","logos"],"a":"logos","r":"Logos er appel til fornuften gennem fakta og logik. Etos appellerer til troværdighed og patos til følelser."},
{"l":7769,"g":8,"b":3,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Hvad er et 'retorisk spørgsmål'?","o":["et spørgsmål, der ikke venter på et svar","et spørgsmål, der stilles til en dommer","et spørgsmål, der kræver lang forberedelse","et spørgsmål, der har flere rigtige svar"],"a":"et spørgsmål, der ikke venter på et svar","r":"'Hvem vil ikke gerne have en bedre skole?' er et retorisk spørgsmål. Det stilles for at overbevise, ikke for at få et svar."},
{"l":7788,"g":8,"b":3,"role":"challenge","insight":"reframing","k":"t","variant":"authored","q":"Hvilken skrivemåde er rigtig: 'Punktet ligger på ___ i koordinatsystemet.'?","o":["x aksen","x-aksen","x'aksen","x:aksen"],"a":"x-aksen","r":"Når et enkelt bogstav sættes sammen med et ord, skrives der bindestreg."},
{"l":7806,"g":8,"b":3,"role":"challenge","insight":"reframing","k":"g","variant":"authored","q":"Hvilket ord er sammensat af tre led?","o":["skolegård","håndklæde","fodboldbane","solskin"],"a":"fodboldbane","r":"'Fodboldbane' består af 'fod', 'bold' og 'bane'. De andre ord har kun to led."},
{"l":7827,"g":8,"b":3,"role":"challenge","insight":"reframing","k":"s","variant":"authored","q":"Find den rigtige form: 'Læreren, som altid ___ gode bøger, gav mig en roman.'","o":["anbefale","anbefalder","anbefalerer","anbefaler"],"a":"anbefaler","r":"Ordet står i nutid i ledsætningen: Læreren anbefaler. Derfor skal det have -r."},
{"l":7844,"g":8,"b":3,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Avisen skriver om de 'implikationer', en beslutning får. Hvad er det?","o":["de følger, der ligger i beslutningen","de personer, der har truffet beslutningen","de møder, der gik forud for beslutningen","de regler, der gjaldt før beslutningen"],"a":"de følger, der ligger i beslutningen","r":"En implikation er det, der følger af noget, selv om det ikke siges direkte. Ordet er beslægtet med 'implicit'."},
{"l":7867,"g":8,"b":3,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Hvilket ord passer i sætningen: 'Hun var så ___, at hun opgav et godt job for at arbejde gratis for en hjælpeorganisation.'","o":["ideel","idealistisk","identisk","idyllisk"],"a":"idealistisk","r":"En idealistisk person handler ud fra høje idealer frem for egen vinding. 'Ideel' siges derimod om noget, der er helt perfekt til formålet."},
{"l":7886,"g":8,"b":3,"role":"challenge","insight":"reframing","k":"f","variant":"authored","q":"Hvad betyder nyhedstrekanten?","o":["At detaljerne står først, og konklusionen kommer sidst","At en nyhed altid skal have præcis tre kilder med","At det vigtigste står først, og detaljerne kommer sidst","At en artikel skal fylde tre spalter i en avis"],"a":"At det vigtigste står først, og detaljerne kommer sidst","r":"I en nyhedsartikel står konklusionen øverst. Så kan læseren stoppe når som helst og alligevel have det vigtigste."},
{"l":7910,"g":8,"b":3,"role":"challenge","insight":"reframing","k":"l","variant":"authored","q":"Læs: 'Det er blevet moderne at kalde alle børn særligt begavede. Hvis alle er særlige, er der ikke mange tilbage at være særlig i forhold til.' Hvad er skribentens logiske pointe?","o":["Der fødes færre begavede børn end i tidligere år","Forældre bør holde op med at rose deres børn så meget","Særligt begavede børn får for lidt hjælp i skolen","Ordet mister sin betydning, når det gælder for alle"],"a":"Ordet mister sin betydning, når det gælder for alle","r":"'Særlig' forudsætter, at nogen ikke er det. Argumentet er sprogligt: Et ord for undtagelsen kan ikke gælde for alle."},
{"l":7927,"g":8,"b":3,"role":"challenge","insight":"reframing","k":"g","variant":"authored","q":"Jakken tilhører Laura. Hvilket stedord skal stå: 'Emma så, at Laura tog ___ jakke på.'?","o":["sin","hendes","deres","dens"],"a":"sin","r":"I ledsætningen er 'Laura' grundled, så 'sin' viser tilbage til hende. 'Hendes' ville betyde Emmas jakke."},
{"l":7949,"g":8,"b":3,"role":"challenge","insight":"reframing","k":"g","variant":"authored","q":"Hvad kalder man det at sige 'gået bort' i stedet for 'død'?","o":["anglicisme","eufemisme","neologisme","dialekt"],"a":"eufemisme","r":"En eufemisme er et mildere ord for noget, der kan være svært at sige direkte."},
{"l":7970,"g":8,"b":3,"role":"challenge","insight":"reframing","k":"f","variant":"authored","q":"Læs: 'Jo mere jeg lærer, desto mindre ved jeg.' Hvilket virkemiddel er der her?","o":["lydord","allitteration","paradoks","sammenligning"],"a":"paradoks","r":"Udsagnet ser selvmodsigende ud, men rummer en sandhed. Det er et paradoks."},
{"l":7990,"g":8,"b":3,"role":"challenge","insight":"reframing","k":"l","variant":"authored","q":"Læs: 'Far siger, at han skal på en lang arbejdsrejse. Han har taget alle sine bøger med, og mor har lagt hans nøgle på bordet. Jeg har tegnet en tegning til ham, som han kan hænge op på hotellet.' Hvad forstår læseren, som fortælleren ikke gør?","o":["At far nok bliver forfremmet efter rejsen","At far ikke kan lide barnets tegninger","At familien snart skal flytte til et hotel","At forældrene sandsynligvis er gået fra hinanden"],"a":"At forældrene sandsynligvis er gået fra hinanden","r":"Bøgerne og den afleverede nøgle passer ikke til en arbejdsrejse. Læseren ser mere end barnet, og det kaldes dramatisk ironi."},
{"l":8008,"g":8,"b":4,"role":"challenge","insight":"reframing","k":"t","variant":"authored","q":"Asta citerer et skilt inde i sin replik. Hvilken sætning er rigtig?","o":["Asta sagde: »Der står 'lukket' på døren.«","Asta sagde »: Der står 'lukket' på døren.«","»Asta sagde: Der står 'lukket' på døren.«","Asta sagde: Der står 'lukket« på døren.»"],"a":"Asta sagde: »Der står 'lukket' på døren.«","r":"Replikken står i dobbelte anførselstegn, og citatet inde i den står i enkelte."},
{"l":8026,"g":8,"b":4,"role":"challenge","insight":"reframing","k":"g","variant":"authored","q":"Hvilken sætning er en opfordring til en gruppe, man selv er med i?","o":["Gå hjem med dem nu.","Lad os gå hjem nu.","De gik hjem for længst.","Vi gik hjem i går."],"a":"Lad os gå hjem nu.","r":"Bydeformen 'lad' sammen med 'os' opfordrer også den, der taler. 'Gå hjem' retter sig kun mod andre."},
{"l":8048,"g":8,"b":4,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Debatten er præget af 'polarisering'. Hvad betyder det?","o":["at folk bliver mere enige med hinanden","at folk mister interessen for emnet","at folk samler sig i to modsatte lejre","at folk taler om emnet på flere sprog"],"a":"at folk samler sig i to modsatte lejre","r":"Ordet kommer af 'pol', som Nordpolen og Sydpolen. Ved polarisering trækkes folk mod hver sin yderlighed, og midten bliver mindre."},
{"l":8070,"g":8,"b":4,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Hvad betyder det, at en beslutningsproces er 'transparent'?","o":["at den er hurtig og går let igennem","at den er hemmelig og kun for få","at den er ny og helt uden regler","at den er åben og let at gennemskue"],"a":"at den er åben og let at gennemskue","r":"'Trans' betyder igennem, så noget transparent kan man se igennem. I overført betydning er det åbent, hvordan beslutningerne er truffet."},
{"l":8092,"g":8,"b":4,"role":"challenge","insight":"reframing","k":"l","variant":"authored","q":"Læs: 'Vindmøller er grimme, siger nogle. Kraftværker var også grimme, men dem kunne man bare ikke se fra sin terrasse.' Hvad antyder skribenten om kritikerne?","o":["At kritikken mest handler om deres egen udsigt","At de ikke ved, hvordan et kraftværk ser ud","At de hellere vil bo tæt på et kraftværk","At vindmøller er kønnere end deres egne terrasser"],"a":"At kritikken mest handler om deres egen udsigt","r":"Skribenten vil vise, at det grimme kun tæller, når det kan ses hjemmefra. Spørgsmålet går på, hvad skribenten antyder, ikke på om det er rigtigt."},
{"l":8108,"g":8,"b":4,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Hvad betyder det, at et land har 'hegemoni' i en region?","o":["det har den største befolkning","det har den dominerende magt","det har de ældste byer","det har den varmeste sommer"],"a":"det har den dominerende magt","r":"Hegemoni kommer af det græske ord for leder. Et land med hegemoni bestemmer dagsordenen over for sine naboer."},
{"l":8130,"g":8,"b":4,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Firmaet har 'konsolideret' sin stilling på markedet. Hvad betyder det?","o":["det har mistet den til andre","det har beskrevet den i en rapport","det har styrket og sikret den","det har opgivet den frivilligt"],"a":"det har styrket og sikret den","r":"Konsolidere kommer af latin 'solidus', som betyder fast. Noget konsolideret er gjort fast og stabilt."},
{"l":8153,"g":8,"b":4,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Hvad betyder det, at der kun forekom 'sporadiske' protester?","o":["at de var meget voldsomme og lange","at de var nøje planlagte og samlede","at de var fredelige og meget glade","at de var spredte og enkeltstående"],"a":"at de var spredte og enkeltstående","r":"Sporadisk betyder, at noget forekommer spredt og uregelmæssigt. Ordet kommer af det græske ord for 'spredt'."},
{"l":8175,"g":8,"b":4,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Hvad vil det sige, at to udtryk er 'ækvivalente'?","o":["at de har samme værdi eller betydning","at de er stavet ens, men lyder forskelligt","at de er opstået i samme land og tid","at de står lige efter hinanden i ordbogen"],"a":"at de har samme værdi eller betydning","r":"'Ækvi' kommer af latin for 'lig' og 'valent' af 'at have værdi'. Ordet bruges både i sprog og i matematik."},
{"l":8195,"g":8,"b":4,"role":"challenge","insight":"reframing","k":"l","variant":"authored","q":"Læs: 'Om tredive år ville hun huske denne dag som den, hvor det hele begyndte. Men nu stod hun bare ved bussen og frøs.' Hvilken virkning har den første sætning?","o":["Den viser, at hun allerede er blevet gammel i fortællingen","Den skaber forventning, fordi fortælleren ved mere end hun","Den forklarer, hvad det var, der begyndte den dag","Den gør det klart, at hun aldrig kommer med bussen"],"a":"Den skaber forventning, fordi fortælleren ved mere end hun","r":"Et spring frem i tiden fortæller, at noget vigtigt er på vej, uden at sige hvad. Det får læseren til at læse videre."},
{"l":8214,"g":8,"b":4,"role":"challenge","insight":"reframing","k":"f","variant":"authored","q":"Læs: 'Jonas så mor komme ind. Hun så træt ud, syntes han. Måske var hun sur på ham. Han vidste det ikke.' Hvilken fortæller har teksten?","o":["alvidende fortæller","jeg-fortæller","begrænset fortæller","neutral fortæller"],"a":"begrænset fortæller","r":"Der står 'han', og vi kender kun Jonas' tanker. Morens tanker må han gætte. Fortælleren er altså bundet til én person."},
{"l":8235,"g":8,"b":4,"role":"challenge","insight":"reframing","k":"g","variant":"authored","q":"Hvilket stedord skal stå: 'Hver af eleverne fik ___ eget skab.'?","o":["sin","sine","sig","sit"],"a":"sit","r":"'Skab' er et intetkønsord i ental, så ejestedordet skal hedde 'sit'. Formen rettes efter det, der ejes."},
{"l":8257,"g":8,"b":4,"role":"challenge","insight":"reframing","k":"g","variant":"authored","q":"Hvilken form passer: 'At vi vandt kampen, var helt ___.'?","o":["utroligt","utrolig","utrolige","utroliges"],"a":"utroligt","r":"En at-sætning som grundled regnes som intetkøn ental, så tillægsordet skal have -t."},
{"l":8279,"g":8,"b":4,"role":"challenge","insight":"reframing","k":"g","variant":"authored","q":"Hvilken genre passer sproget til: 'Det må konstateres, at resultaterne ikke lever op til forventningerne.'?","o":["en sms","en rapport","en dagbog","en vittighed"],"a":"en rapport","r":"Upersonligt sprog, passiv og faste, formelle vendinger er typisk for rapporter og officielle tekster."},
{"l":8303,"g":8,"b":5,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Avisen kalder billetprisen 'eksorbitant'. Hvad mener avisen?","o":["at den er overraskende lav","at den er fastsat ved lov","at den er urimeligt høj","at den ændrer sig hver uge"],"a":"at den er urimeligt høj","r":"Eksorbitant kommer af latin og betyder egentlig 'uden for sporet'. Ordet bruges om priser og krav, der går langt ud over det rimelige."},
{"l":8320,"g":8,"b":5,"role":"challenge","insight":"reframing","k":"l","variant":"authored","q":"Læs: 'Nogle ønsker forbud mod privat fyrværkeri på grund af skader og hensynet til dyr. Andre ser nytårsfyrværkeri som en vigtig tradition. Politikerne har endnu ikke stemt om forslaget.' Hvilken sætning ville gøre teksten mindre neutral, hvis den blev tilføjet?","o":["Afstemningen ventes at finde sted i marts.","Begge sider har skrevet til byrådet i år.","Forslaget blev fremsat i løbet af efteråret.","Det er på høje tid at stoppe dette vanvid."],"a":"Det er på høje tid at stoppe dette vanvid.","r":"Ordene 'på høje tid' og 'vanvid' tager stilling. De andre sætninger er oplysninger, der kan efterprøves."},
{"l":8345,"g":8,"b":5,"role":"challenge","insight":"reframing","k":"g","variant":"authored","q":"Hvilket ord er udeladt i relativsætningen: 'Bogen, jeg læser lige nu, er spændende.'?","o":["som","der","at","om"],"a":"som","r":"Man kan udelade 'som', når det ikke er grundled i relativsætningen. Her er 'jeg' grundled."},
{"l":8367,"g":8,"b":5,"role":"challenge","insight":"reframing","k":"g","variant":"authored","q":"Hvilken sætning betyder, at hun ikke lagde mærke til fejlen?","o":["Hun så teksten igennem.","Hun overså fejlen i teksten.","Hun så over på teksten.","Hun rettede fejlen i teksten."],"a":"Hun overså fejlen i teksten.","r":"Det sammensatte verbum 'overse' har en anden betydning end 'se over'. Forleddet kan altså ændre ordets mening."},
{"l":8388,"g":8,"b":5,"role":"challenge","insight":"reframing","k":"f","variant":"authored","q":"Hvilken roman af Hans Scherfig er en satire over en stiv og gammeldags latinskole?","o":["Ved Vejen","Niels Lyhne","Det forsømte forår","Barndommens gade"],"a":"Det forsømte forår","r":"'Det forsømte forår' fra 1940 er en krimi og en bidende satire over den gamle latinskole."},
{"l":8411,"g":8,"b":5,"role":"challenge","insight":"reframing","k":"g","variant":"authored","q":"Hvad er verballeddets form i: 'Huset var blevet solgt, før vi nåede frem.'?","o":["passiv førnutid","aktiv datid","aktiv nutid","passiv førdatid"],"a":"passiv førdatid","r":"'Var' viser førdatid, og 'blevet solgt' viser passiv. Handlingen skete før et andet tidspunkt i fortiden."},
{"l":8430,"g":8,"b":5,"role":"challenge","insight":"reframing","k":"f","variant":"authored","q":"Hvem rejste i 1800-tallet rundt i Jylland og indsamlede tusindvis af sagn og eventyr?","o":["Evald Tang Kristensen","Georg Brandes","Herman Bang","Ludvig Holberg"],"a":"Evald Tang Kristensen","r":"Læreren Evald Tang Kristensen skrev en enorm mængde folkeminder ned, så de ikke gik tabt."},
{"l":8453,"g":8,"b":5,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Efter flere måneders belejring valgte fæstningen at 'kapitulere'. Hvad betyder det?","o":["at gå til modangreb","at overgive sig","at bede om ny forsyning","at sende bud til kongen"],"a":"at overgive sig","r":"Når man kapitulerer, opgiver man kampen og overgiver sig. Ordet bruges også i overført betydning, for eksempel om at give efter for pres."},
{"l":8472,"g":8,"b":5,"role":"challenge","insight":"reframing","k":"f","variant":"authored","q":"Læs: 'Sebastian vil gerne sige sandheden, men er bange for at miste sin bedste ven. Hele natten ligger han vågen og vender det i hovedet.' Hvilken slags konflikt er der tale om?","o":["ydre konflikt med naturen","ydre konflikt med samfundet","indre konflikt i personen","konflikt mellem to grupper"],"a":"indre konflikt i personen","r":"Konflikten foregår inde i Sebastian, der er splittet mellem to ønsker. Derfor er den indre."},
{"l":8492,"g":8,"b":5,"role":"challenge","insight":"reframing","k":"t","variant":"authored","q":"Efter hvilket ord kræves der komma: 'Han sagde at hvis det regnede ville han blive hjemme.'?","o":["det","ville","han","regnede"],"a":"regnede","r":"Ledsætningen 'hvis det regnede' slutter efter 'regnede'. Slutkommaet skal altid sættes."},
{"l":8514,"g":8,"b":5,"role":"deep_challenge","insight":"perspective_shift","k":"t","variant":"authored","q":"Hvilket ord har fået stort med urette: 'Hun flyttede fra Nordjylland til Sydfrankrig og blev Franskmand.'?","o":["Franskmand","Nordjylland","Sydfrankrig","Hun"],"a":"Franskmand","r":"Ord for nationalitet skrives med lille. Nordjylland og Sydfrankrig er geografiske navne."},
{"l":8536,"g":8,"b":5,"role":"deep_challenge","insight":"perspective_shift","k":"t","variant":"authored","q":"Hvilken sætning er tegnsat rigtigt om turen mod Skagen?","o":["Da vi havde pakket bilen kørte vi mod Skagen, men vi nåede kun til Aalborg.","Da vi havde pakket bilen, kørte vi mod Skagen, men vi nåede kun til Aalborg.","Da vi havde pakket bilen, kørte vi mod Skagen men, vi nåede kun til Aalborg.","Da vi havde pakket, bilen kørte vi mod Skagen, men vi nåede kun til Aalborg."],"a":"Da vi havde pakket bilen, kørte vi mod Skagen, men vi nåede kun til Aalborg.","r":"Der skal komma efter ledsætningen, der slutter med 'bilen', og foran 'men' mellem de to hovedsætninger."},
{"l":8558,"g":8,"b":5,"role":"deep_challenge","insight":"perspective_shift","k":"t","variant":"authored","q":"Hvilket komma har man lov til at udelade efter Dansk Sprognævns regler?","o":["Slutkommaet efter en ledsætning","Kommaet i en opremsning af ting","Startkommaet foran en ledsætning","Kommaet mellem to hovedsætninger"],"a":"Startkommaet foran en ledsætning","r":"Startkommaet er valgfrit. De andre kommaer er krav, fordi de markerer grænser, læseren har brug for."},
{"l":8585,"g":9,"b":1,"role":"deep_challenge","insight":"perspective_shift","k":"f","variant":"authored","q":"Hvilket litterært tidsskrift udkom i Danmark fra 1948 til 1953 og samlede en gruppe unge modernister?","o":["Vindrosen","Hvedekorn","Kritik","Heretica"],"a":"Heretica","r":"Heretica udkom 1948–53, og kredsen søgte nye værdier efter Anden Verdenskrig."},
{"l":8608,"g":9,"b":1,"role":"deep_challenge","insight":"perspective_shift","k":"g","variant":"authored","q":"Dansk, svensk og norsk ligner hinanden, fordi de hører til samme gren af de germanske sprog. Hvilken gren?","o":["nordgermansk","vestgermansk","østgermansk","vestslavisk"],"a":"nordgermansk","r":"De nordiske sprog dansk, svensk, norsk, islandsk og færøsk er nordgermanske. Engelsk og tysk er derimod vestgermanske."},
{"l":8635,"g":9,"b":1,"role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"authored","q":"Rygterne 'underminerede' trænerens autoritet. Hvad gjorde rygterne ved den?","o":["styrkede den meget hurtigt","svækkede den lidt efter lidt","gjorde den kendt i hele byen","lod den være helt uberørt"],"a":"svækkede den lidt efter lidt","r":"Ordet stammer fra krigsførelse, hvor man gravede gange under en mur. I overført betydning svækker man noget indefra."},
{"l":8657,"g":9,"b":1,"role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"authored","q":"Hvad er en 'kverulant'?","o":["en person, der er dygtig til at synge i kor","en person, der gerne hjælper sine naboer","en person, der hele tiden klager over småting","en person, der sjældent siger noget som helst"],"a":"en person, der hele tiden klager over småting","r":"Latin 'queri' betyder at klage. En kverulant finder hele tiden noget at brokke sig over."},
{"l":8674,"g":9,"b":1,"role":"deep_challenge","insight":"perspective_shift","k":"g","variant":"authored","q":"Ordet 'ting' har fire bogstaver. Hvor mange lyde har det?","o":["fire lyde","to lyde","fem lyde","tre lyde"],"a":"tre lyde","r":"Bogstaverne n og g står tilsammen for én lyd, [ŋ]. Derfor består ordet af t, i og ng-lyden."},
{"l":8696,"g":9,"b":1,"role":"deep_challenge","insight":"perspective_shift","k":"g","variant":"authored","q":"'En husbåd' er en båd, og 'et bådhus' er et hus. Hvilket led afgør betydning og køn i sammensatte ord?","o":["det sidste led","det første led","det længste led","det korteste led"],"a":"det sidste led","r":"Det sidste led er hovedleddet, og det første led præciserer det. Derfor er en husbåd en slags båd, og ordet får bådens køn."},
{"l":8717,"g":9,"b":1,"role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"authored","q":"Mellem de to naboer var der en 'latent' konflikt. Hvad betyder det?","o":["Den var åben og kendt af alle","Den var skjult, men kunne bryde ud","Den var løst for mange år siden","Den handlede om noget uvigtigt"],"a":"Den var skjult, men kunne bryde ud","r":"Latin 'latere' betyder at ligge skjult. Noget latent er til stede, selvom det endnu ikke kan ses."},
{"l":8740,"g":9,"b":1,"role":"deep_challenge","insight":"perspective_shift","k":"g","variant":"authored","q":"Hvilket af disse morfemer er bundet, så det ikke kan stå alene som et ord?","o":["hus","sol","-hed","bog"],"a":"-hed","r":"Et bundet morfem skal sidde på et andet morfem, som i 'frihed'. 'Hus', 'sol' og 'bog' er frie morfemer, der kan stå alene."},
{"l":8761,"g":9,"b":1,"role":"deep_challenge","insight":"perspective_shift","k":"f","variant":"authored","q":"Læs: 'Lotte satte sig på sengen. Hvorfor skulle hun altid være den, der gav sig? Det var ikke retfærdigt!' Hvilken fremstillingsform er de to sidste sætninger?","o":["direkte tale","referat","neutral beskrivelse","fri indirekte tale"],"a":"fri indirekte tale","r":"Vi får Lottes tanker i fortællerens tredjepersonsform uden 'hun tænkte'. Stemmerne glider sammen, og det kaldes fri indirekte tale."},
{"l":8783,"g":9,"b":1,"role":"deep_challenge","insight":"perspective_shift","k":"f","variant":"authored","q":"Hvilken forfatter skrev 'Forvandlingen', hvor en mand vågner op som et kæmpestort insekt?","o":["Franz Kafka","James Joyce","Henrik Ibsen","Albert Camus"],"a":"Franz Kafka","r":"Franz Kafkas 'Forvandlingen' er et hovedværk i den moderne litteratur. Det uhyggelige fortælles helt roligt."},
{"l":8802,"g":9,"b":1,"role":"deep_challenge","insight":"perspective_shift","k":"l","variant":"authored","q":"Læs: 'Hun lagde kuverten på bordet. Det var jo ikke hendes skyld. Hun havde sagt det til ham, mange gange, og hvem havde nogensinde lyttet til hende?' Hvis stemme hører man i de to sidste sætninger?","o":["En neutral fortæller, der vurderer hændelsen udefra","Personens egne tanker, gengivet af fortælleren","Mandens svar på det, hun har sagt til ham","En anden person, der står og ser på hende"],"a":"Personens egne tanker, gengivet af fortælleren","r":"Det forsvarende 'jo' og det retoriske spørgsmål er hendes egne tanker, selv om der står 'hun'. Det kaldes dækket direkte tale."},
{"l":8822,"g":9,"b":1,"role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"authored","q":"Udtrykket 'at tage benene på nakken' er et idiom. Hvad kendetegner et idiom?","o":["Det kan kun bruges i digte og sange","Det stammer fra en bestemt dansk forfatter","Betydningen fremgår ikke af de enkelte ord","Det er gået helt af brug i dag"],"a":"Betydningen fremgår ikke af de enkelte ord","r":"Man skal kende udtrykket som helhed. Her betyder det at løbe hurtigt væk, selvom ordene siger noget andet."},
{"l":8840,"g":9,"b":1,"role":"deep_challenge","insight":"perspective_shift","k":"t","variant":"authored","q":"Hvilken sætning er rigtig, når tiltalen står inde i sætningen?","o":["Du skal, Clara huske nøglen i dag.","Du skal Clara, huske nøglen i dag.","Du skal Clara huske, nøglen i dag.","Du skal, Clara, huske nøglen i dag."],"a":"Du skal, Clara, huske nøglen i dag.","r":"En tiltale midt i en sætning skal have komma på begge sider."},
{"l":8865,"g":9,"b":2,"role":"deep_challenge","insight":"perspective_shift","k":"s","variant":"authored","q":"Hvilken form passer? 'Selvom de fleste i klassen ___ film, vil Noor hellere læse bogen.'","o":["foretrækker","foretrække","foretræker","foretrækkerer"],"a":"foretrækker","r":"Ordet står i nutid i ledsætningen: De foretrækker. Derfor skal det have -r."},
{"l":8883,"g":9,"b":2,"role":"deep_challenge","insight":"perspective_shift","k":"g","variant":"authored","q":"Hvilken sætning er skrevet i tydelig nominalstil?","o":["Læreren vurderede, hvordan eleverne læste.","Der blev foretaget en vurdering af elevernes læsning.","Eleverne læste højt, og læreren lyttede.","Læreren lyttede til alle eleverne i klassen."],"a":"Der blev foretaget en vurdering af elevernes læsning.","r":"Nominalstil samler indholdet i navneord som 'vurdering' og 'læsning' i stedet for udsagnsord. Det gør sætningen tungere, og aktøren forsvinder."},
{"l":8905,"g":9,"b":2,"role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"authored","q":"Hvad betyder det at tage en modgang med 'stoisk ro'?","o":["at trække sig helt væk fra andre mennesker","at gøre det hele til grin med vittigheder","at bevare fatningen, uanset hvad der sker","at give andre skylden for det, der skete"],"a":"at bevare fatningen, uanset hvad der sker","r":"Stoikerne var græske filosoffer, der lærte, at man ikke skal lade sig styre af det, man ikke selv er herre over."},
{"l":8925,"g":9,"b":2,"role":"deep_challenge","insight":"perspective_shift","k":"s","variant":"authored","q":"Hvad er rigtigt? 'Hun fortalte om sit projekt med stor ___.'","o":["entuziasme","entusiame","entussiasme","entusiasme"],"a":"entusiasme","r":"Ordet kommer fra græsk og har ét s før i'et og et s foran -me."},
{"l":8944,"g":9,"b":2,"role":"deep_challenge","insight":"perspective_shift","k":"t","variant":"authored","q":"Hvilket ord har fået stort med urette: 'Lægen tog et Røntgenbillede af Kristoffers arm i Silkeborg.'?","o":["Røntgenbillede","Kristoffers","Silkeborg","Lægen"],"a":"Røntgenbillede","r":"Ordet er et almindeligt navneord og skrives med lille, selvom første led stammer fra et efternavn."},
{"l":8965,"g":9,"b":2,"role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"authored","q":"Hvilket ord passer: 'At regn gør jorden våd, er et eksempel på ___: Den ene hændelse er direkte årsag til den anden.'","o":["kontinuitet","kausalitet","kapacitet","kvantitet"],"a":"kausalitet","r":"Kausalitet kommer af latin 'causa', årsag. Ordet bruges om forholdet mellem årsag og virkning."},
{"l":8985,"g":9,"b":2,"role":"deep_challenge","insight":"perspective_shift","k":"s","variant":"authored","q":"Hvad er rigtigt? 'Det giver stor ___ at vinde en Nobelpris.'","o":["præstige","prestisje","prestige","prestiche"],"a":"prestige","r":"Ordet kommer fra fransk og skrives med e, ikke æ, og det ender på -ige."},
{"l":9004,"g":9,"b":2,"role":"deep_challenge","insight":"perspective_shift","k":"g","variant":"authored","q":"Hvilken sætning er skrevet i gammeldags kancellistil?","o":["Jeg skriver for at fortælle dig noget vigtigt om mødet.","Hej, jeg ville bare lige sige noget om det møde.","Mødet bliver på tirsdag, så husk at tage din bog med.","Undertegnede skal herved tillade sig at meddele Dem følgende."],"a":"Undertegnede skal herved tillade sig at meddele Dem følgende.","r":"Kancellistil er det tunge, formelle sprog fra gamle myndigheder. Ord som 'undertegnede' og 'herved' er typiske for den stil."},
{"l":9025,"g":9,"b":2,"role":"deep_challenge","insight":"perspective_shift","k":"f","variant":"authored","q":"Læs: 'Jeg husker lugten. Jeg husker lyset. Jeg husker hendes hænder.' Hvilken figur er det?","o":["anafor","epifor","kiasme","synæstesi"],"a":"anafor","r":"Anafor er gentagelse af det samme ord eller led i begyndelsen af flere sætninger."},
{"l":9047,"g":9,"b":2,"role":"deep_challenge","insight":"perspective_shift","k":"f","variant":"authored","q":"Læs: 'Man skal spise for at leve, ikke leve for at spise.' Hvilken figur er det?","o":["anafor","kiasme","eufemisme","synæstesi"],"a":"kiasme","r":"Leddene bytter plads i anden halvdel: spise-leve bliver til leve-spise. Den krydsstilling kaldes en kiasme."},
{"l":9069,"g":9,"b":2,"role":"deep_challenge","insight":"perspective_shift","k":"f","variant":"authored","q":"Læs: 'Violinen spillede en skarp, citrongul tone.' Hvilken figur er der her?","o":["metonymi","kiasme","synæstesi","anafor"],"a":"synæstesi","r":"En lyd beskrives med en farve, altså blandes to sanser. Det kaldes synæstesi."},
{"l":9088,"g":9,"b":2,"role":"deep_challenge","insight":"perspective_shift","k":"l","variant":"authored","q":"Læs: 'Min onkel er meget vellidt. Han har så mange venner, at de kommer hver måned og spørger efter ham. Når han ikke er hjemme, beder de mig sige, at de kommer igen, og at de ikke har glemt ham.' Hvad er det, barnet ikke forstår?","o":["At onklen er rejst bort uden at sige det","At vennerne egentlig vil besøge barnet selv","At onklen ikke selv ved, hvor han bor henne","At de besøgende nok vil have noget, han skylder dem"],"a":"At de besøgende nok vil have noget, han skylder dem","r":"Barnet opfatter besøgene som venskab, men 'ikke glemt ham' lyder som en trussel. Læseren ved mere end fortælleren."},
{"l":9105,"g":9,"b":2,"role":"deep_challenge","insight":"perspective_shift","k":"s","variant":"authored","q":"Find stavemåden: 'Bladet gjorde grin med de kendte på en skarp og sjov måde; det var ren ___.'","o":["satire","sattire","satyre","zatire"],"a":"satire","r":"Ordet har ét t og skrives med i."},
{"l":9124,"g":9,"b":2,"role":"deep_challenge","insight":"perspective_shift","k":"f","variant":"authored","q":"Hvilken bog af George Orwell er en allegori, hvor dyrene på en gård overtager magten?","o":["Fluernes Herre","Kammerat Napoleon","Robinson Crusoe","Gullivers rejser"],"a":"Kammerat Napoleon","r":"Dyrene i 'Kammerat Napoleon' står for mennesker og magthavere. Hele fortællingen skal læses som et billede på en revolution, der går galt."},
{"l":9147,"g":9,"b":3,"role":"deep_challenge","insight":"perspective_shift","k":"l","variant":"authored","q":"Læs: 'Et kort er ikke landskabet. Det udelader lugten, vejret og alle de hække, der er vokset siden. Det samme gælder et karakterblad.' Hvad vil skribenten sige om karakterbladet?","o":["Det er ubrugeligt og bør straks afskaffes","Det er mere præcist end de fleste kort","Det er et forenklet billede, der udelader meget","Det ændrer sig hurtigere end et landskab"],"a":"Det er et forenklet billede, der udelader meget","r":"Et kort er nyttigt, men ufuldstændigt. Skribenten afviser ikke karakterbladet, men minder om dets grænser."},
{"l":9168,"g":9,"b":3,"role":"deep_challenge","insight":"perspective_shift","k":"f","variant":"authored","q":"Hvilken menneskelig svaghed afslører H.C. Andersens 'Kejserens nye klæder' især?","o":["Grådighed efter mad og drikke","Dovenskab på arbejdet ved hoffet","Vrede mod de mennesker, der er fattige","Frygten for at sige sandheden højt"],"a":"Frygten for at sige sandheden højt","r":"Alle lader, som om de ser klæderne, fordi de ikke tør skille sig ud. Kun barnet siger, hvad det ser."},
{"l":9190,"g":9,"b":3,"role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"authored","q":"Hvad er en 'allegori'?","o":["en fortælling med en dybere, billedlig mening","en fortælling om kendte personers liv","en fortælling, der altid er på rim","en fortælling om noget, der faktisk er sket"],"a":"en fortælling med en dybere, billedlig mening","r":"I en allegori står personer og hændelser for noget andet, for eksempel abstrakte begreber. Græsk 'allegoria' betyder at sige noget andet."},
{"l":9207,"g":9,"b":3,"role":"deep_challenge","insight":"perspective_shift","k":"l","variant":"authored","q":"Læs: 'Før den nye læsemetode læste 40 procent af eleverne godt. Efter et år var tallet 60 procent. Samme år blev den nationale læsetest ændret og gjort lettere.' Hvad betyder den sidste oplysning for vurderingen af metoden?","o":["Metoden er med sikkerhed en fiasko for de svageste elever","Stigningen kan helt eller delvist skyldes den lettere test","Testen viser nu mere præcist, hvor gode eleverne er blevet","Eleverne har læst lige så godt efter som før metoden"],"a":"Stigningen kan helt eller delvist skyldes den lettere test","r":"Når to ting ændres på samme tid, kan man ikke sige, hvilken der gjorde forskellen. Metoden er hverken bevist eller afvist."},
{"l":9227,"g":9,"b":3,"role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"authored","q":"Hvad betyder det, at forholdene i et køkken er 'kritisable'?","o":["De er tæt på at bryde sammen","De er blevet rost af kritikerne","De fortjener at blive kritiseret","De er meget svære at undersøge"],"a":"De fortjener at blive kritiseret","r":"Kritisabel betyder 'som kan og bør kritiseres'. Ordet må ikke forveksles med 'kritisk', som bruges om en farlig situation."},
{"l":9246,"g":9,"b":3,"role":"deep_challenge","insight":"perspective_shift","k":"g","variant":"authored","q":"Hvilken dansk sprogforsker var i begyndelsen af 1800-tallet med til at grundlægge den sammenlignende sprogvidenskab?","o":["H.C. Ørsted","N.F.S. Grundtvig","Ludvig Holberg","Rasmus Rask"],"a":"Rasmus Rask","r":"Rasmus Rask sammenlignede sprog og viste, at de hænger sammen gennem faste lydforhold. Ørsted var fysiker, Grundtvig præst og digter, og Holberg var dramatiker."},
{"l":9267,"g":9,"b":3,"role":"deep_challenge","insight":"perspective_shift","k":"f","variant":"authored","q":"Hvilket tema er centralt i Karen Blixens fortællinger?","o":["Skæbnen og menneskets rolle i en større historie","Arbejdernes kamp for bedre løn på fabrikkerne","Unges brug af moderne teknik og sociale medier","Købmænds arbejde med handel i mindre provinsbyer"],"a":"Skæbnen og menneskets rolle i en større historie","r":"Blixens personer indgår ofte i en større fortælling og må tage imod deres skæbne med værdighed."},
{"l":9289,"g":9,"b":3,"role":"deep_challenge","insight":"perspective_shift","k":"f","variant":"authored","q":"Hvad er autofiktion?","o":["En tekst, der er skrevet af en computer uden hjælp","En tekst, der blander forfatterens liv med opdigtet stof","En tekst, der handler om biler og andre køretøjer","En tekst, der gengiver en sand hændelse helt nøjagtigt"],"a":"En tekst, der blander forfatterens liv med opdigtet stof","r":"I autofiktion kan fortælleren ligne forfatteren, men man ved ikke, hvad der er sandt. Det leger med grænsen mellem liv og digtning."},
{"l":9310,"g":9,"b":3,"role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"authored","q":"Hvad er en 'esoterisk' viden?","o":["viden, der er let tilgængelig for alle i samfundet","viden, der særligt er rettet mod helt nye begyndere","viden, der kun er for en snæver kreds af indviede","viden, der stammer fra gamle og pålidelige opslagsværker"],"a":"viden, der kun er for en snæver kreds af indviede","r":"Græsk 'esoterikos' betyder indre. Noget esoterisk er forbeholdt de få, som er kommet indenfor."},
{"l":9332,"g":9,"b":3,"role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"authored","q":"Hvad hævder man i 'værdirelativisme'?","o":["at der findes én sandhed for alle til alle tider","at tiden kan måles helt præcist overalt","at familien er samfundets vigtigste enhed","at værdier afhænger af kultur og ståsted"],"a":"at værdier afhænger af kultur og ståsted","r":"Relativ betyder afhængig af noget andet. Relativisten mener, at ingen værdi gælder uafhængigt af sin sammenhæng."},
{"l":9350,"g":9,"b":3,"role":"deep_challenge","insight":"perspective_shift","k":"l","variant":"authored","q":"Læs: 'Forskning viser, at lektier gavner elever i gymnasiet. Altså bør børn i 1. klasse have mere for.' Hvad er problemet med slutningen?","o":["Et resultat for én aldersgruppe overføres uden videre til en anden","Gymnasieelever laver i forvejen flere lektier end børn i 1. klasse","Forskningen viser ikke, hvor mange lektier en gymnasieelev har","Børn i 1. klasse har ikke lært at læse lektieopgaver endnu"],"a":"Et resultat for én aldersgruppe overføres uden videre til en anden","r":"Det, der gælder for store elever, behøver ikke at gælde små. Slutningen kræver et led, som ikke er vist."},
{"l":9373,"g":9,"b":3,"role":"deep_challenge","insight":"perspective_shift","k":"l","variant":"authored","q":"Læs: 'Forord: Alle personer i denne bog er opdigtede, og enhver lighed med min mor er tilfældig.' Hvad gør forfatteren?","o":["Oplyser sagligt og neutralt, at bogen ikke handler om virkelige folk","Antyder med et glimt i øjet, at moren er forbillede for en person","Giver sin mor en tak for hjælpen med at skrive bogen","Advarer læseren om, at moren er ukendt for forfatteren"],"a":"Antyder med et glimt i øjet, at moren er forbillede for en person","r":"Det sædvanlige forbehold gælder 'virkelige personer', men her nævnes kun moren. Præcisionen røber det, der benægtes."},
{"l":9390,"g":9,"b":3,"role":"deep_challenge","insight":"perspective_shift","k":"s","variant":"authored","q":"Vælg rigtigt: 'Gamle fotos kan vække ___ og minder om barndommen.'","o":["nostalgie","nosstalgi","nostalgi","nostalchi"],"a":"nostalgi","r":"Ordet kommer fra græsk og ender på -algi uden e."},
{"l":9412,"g":9,"b":3,"role":"deep_challenge","insight":"perspective_shift","k":"t","variant":"authored","q":"Efter hvilket ord skal der komma: 'Uanset hvad du vælger står jeg ved din side.'?","o":["hvad","står","side","vælger"],"a":"vælger","r":"'Uanset hvad du vælger' er en ledsætning, der står først."},
{"l":9437,"g":9,"b":4,"role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"authored","q":"I den græske tragedie falder helten ofte på grund af 'hubris'. Hvad er det?","o":["en overmodig selvtillid","en dyb skam","et uheldigt tilfælde","en arvelig forbandelse"],"a":"en overmodig selvtillid","r":"Hubris er det overmod, der får mennesket til at sætte sig op mod guderne. Det bliver heltens fald."},
{"l":9457,"g":9,"b":4,"role":"deep_challenge","insight":"perspective_shift","k":"l","variant":"authored","q":"Læs: 'Lægen talte i lange sætninger. Mor nikkede på de rigtige steder og stillede to kloge spørgsmål. I bilen spurgte hun mig, hvad han havde sagt.' Hvad afslører den sidste sætning?","o":["At hun har spurgt barnet for at teste det","At hun i chok ikke har kunnet tage noget ind","At lægen talte så lavt, at ingen af dem hørte det","At hun ikke interesserede sig for samtalen"],"a":"At hun i chok ikke har kunnet tage noget ind","r":"Hun virkede rolig, men intet nåede ind. Det ydre kontrol-billede bryder sammen med en enkelt replik."},
{"l":9477,"g":9,"b":4,"role":"deep_challenge","insight":"perspective_shift","k":"g","variant":"authored","q":"Hvor mange kasus havde navneord i oldnordisk?","o":["to kasus","tre kasus","fire kasus","seks kasus"],"a":"fire kasus","r":"Oldnordisk havde nominativ, akkusativ, dativ og genitiv, ligesom tysk har i dag. I moderne dansk er kun ejefaldet tilbage hos navneord."},
{"l":9497,"g":9,"b":4,"role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"authored","q":"Forleddet 'omni-' er latin. Hvad betyder det i 'omnipotent'?","o":["halv eller delvis","dobbelt eller to","ny eller ung","al eller alt"],"a":"al eller alt","r":"Omnipotent betyder almægtig. Det samme led findes i 'omnivor', altædende."},
{"l":9520,"g":9,"b":4,"role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"authored","q":"Hvad kendetegner et 'kleptokrati'?","o":["Lederne bruger magten til at berige sig selv","Lederne bliver valgt af landets dygtigste","Lederne deler magten med landets præster","Lederne må kun sidde i fire år"],"a":"Lederne bruger magten til at berige sig selv","r":"Græsk 'kleptes' betyder tyv. Ordet er i familie med 'kleptoman'."},
{"l":9540,"g":9,"b":4,"role":"deep_challenge","insight":"perspective_shift","k":"s","variant":"authored","q":"Vælg rigtigt: 'I nogle lande er der ___ af aviser, så ikke alt må skrives.'","o":["sensur","censur","censurr","cænsur"],"a":"censur","r":"Ordet begynder med c, selvom det lyder som s, og det har kun ét r."},
{"l":9564,"g":9,"b":4,"role":"deep_challenge","insight":"perspective_shift","k":"l","variant":"authored","q":"Læs: 'Romanen er velskrevet på samme måde, som en hotelreception er venlig: korrekt, tandløs og uden interesse for, hvem man er.' Hvad er anmelderens dom?","o":["Bogen er elendigt skrevet og uden nogen sproglig kvalitet","Bogen foregår på et hotel og handler om en receptionist","Bogen er teknisk fin, men mangler personlighed og nærvær","Bogen er rørende, fordi personerne er så venlige"],"a":"Bogen er teknisk fin, men mangler personlighed og nærvær","r":"Rosen 'velskrevet' tages næsten tilbage med sammenligningen. Hotelvenlighed er høflig, men upersonlig."},
{"l":9580,"g":9,"b":4,"role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"authored","q":"Hvad gør en 'patogen' bakterie?","o":["Den nedbryder plast","Den hjælper fordøjelsen","Den lever kun i saltvand","Den fremkalder sygdom"],"a":"Den fremkalder sygdom","r":"Pato- kommer af græsk 'pathos', lidelse, og -gen betyder skabe. Mange bakterier er harmløse, men de patogene gør os syge."},
{"l":9599,"g":9,"b":4,"role":"deep_challenge","insight":"perspective_shift","k":"l","variant":"authored","q":"Læs: 'Bussen stoppede, som den plejede, ved den lukkede station. Chaufføren åbnede dørene, og ingen steg af, og ingen steg på. Så lukkede han dem igen. Det stod i køreplanen.' Hvilken stemning skabes?","o":["Det absurde i at følge regler, der har mistet mening","Det hyggelige ved en rolig og velkendt busrute","Det uhyggelige ved en station, hvor der spøger","Det sørgelige ved en chauffør, der snart mister sit job"],"a":"Det absurde i at følge regler, der har mistet mening","r":"Handlingen bliver udført, fordi den står på papiret. Den tørre sidste sætning understreger det meningsløse."},
{"l":9620,"g":9,"b":4,"role":"deep_challenge","insight":"perspective_shift","k":"g","variant":"authored","q":"Hvilken af disse sætninger er en spaltning?","o":["Det var koldt i Odense den dag.","Det var i Odense, at Mira blev født.","Det regner ofte meget i Odense.","Det hus ligger midt i Odense."],"a":"Det var i Odense, at Mira blev født.","r":"En spaltning kan føres tilbage til én sætning: 'Mira blev født i Odense.' De andre sætninger begynder også med 'Det', men kan ikke omskrives på den måde."},
{"l":9642,"g":9,"b":4,"role":"deep_challenge","insight":"perspective_shift","k":"g","variant":"authored","q":"På svensk hedder det 'det stora huset', på dansk 'det store hus'. Hvad er forskellen?","o":["Svensk har slet intet kendeord i bestemt form.","Dansk har kendeord både foran og bag på navneordet.","Svensk har kendeord både foran og bag på navneordet.","Dansk har slet ingen tillægsord foran navneord."],"a":"Svensk har kendeord både foran og bag på navneordet.","r":"Svensk bruger både kendeordet 'det' og endelsen -et på 'huset'. Dansk nøjes med det foranstillede kendeord, når der står et tillægsord."},
{"l":9663,"g":9,"b":4,"role":"deep_challenge","insight":"perspective_shift","k":"f","variant":"authored","q":"Hvilken læsemåde bruger man, når man tolker en persons drømme og skjulte drifter, inspireret af Sigmund Freud?","o":["biografisk læsning","nykritisk læsning","nyhedsmæssig læsning","psykoanalytisk læsning"],"a":"psykoanalytisk læsning","r":"Den psykoanalytiske læsning leder efter det ubevidste i personerne og teksten, f.eks. skjulte ønsker og frygt."},
{"l":9685,"g":9,"b":4,"role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"authored","q":"En forsker tvinger sine data ned i en 'prokrustesseng'. Hvad er det?","o":["en stiv ramme, som virkeligheden presses ind i","en blød overgang fra én fase til den næste","en bekvem løsning, som alle parter er enige om","en fælde for uforsigtige og hastige modstandere"],"a":"en stiv ramme, som virkeligheden presses ind i","r":"I myten fik røveren Prokrustes sine gæster til at passe til sengen. I dag bruges ordet om et skema, der ikke passer til sagen."},
{"l":9705,"g":9,"b":4,"role":"deep_challenge","insight":"perspective_shift","k":"s","variant":"authored","q":"Find stavemåden: 'Rapporten viste et ___ fald i bestanden af bier.'","o":["foruroligene","foruroligende","forurolignede","forurolende"],"a":"foruroligende","r":"Ordet er dannet af 'forurolige' med -ende, så der er både g og d."},
{"l":9724,"g":9,"b":5,"role":"deep_challenge","insight":"perspective_shift","k":"t","variant":"authored","q":"Hvilken sætning er tegnsat helt rigtigt om bogen af Karen Blixen?","o":["Bogen som Selma lånte handler om Karen Blixen, der skrev »Den afrikanske farm«.","Bogen, som Selma lånte handler om Karen Blixen, der skrev »Den afrikanske farm«.","Bogen, som Selma lånte, handler om Karen Blixen, der skrev »Den afrikanske farm«.","Bogen, som Selma, lånte handler om Karen Blixen der skrev »Den afrikanske farm«."],"a":"Bogen, som Selma lånte, handler om Karen Blixen, der skrev »Den afrikanske farm«.","r":"Den indskudte ledsætning 'som Selma lånte' skal afsluttes med komma efter 'lånte'."},
{"l":9745,"g":9,"b":5,"role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"authored","q":"Hvilket ord passer: 'Hans ___ indblanding i deres samtale gjorde stemningen trykket.'","o":["taktfulde","diskrete","velkomne","utidige"],"a":"utidige","r":"Utidig betyder upassende og på et dårligt tidspunkt. Derfor bliver stemningen trykket af indblandingen."},
{"l":9765,"g":9,"b":5,"role":"deep_challenge","insight":"perspective_shift","k":"s","variant":"authored","q":"Find rigtigt: 'Hun gav ham et ___ for hans flotte tale.'","o":["kompliment","komplement","komplimænt","komplemang"],"a":"kompliment","r":"Med i betyder ordet ros. 'Komplement' med e er noget, der gør noget andet helt."},
{"l":9785,"g":9,"b":5,"role":"deep_challenge","insight":"perspective_shift","k":"g","variant":"authored","q":"Hvilket af disse sprogpar hører ikke til den indoeuropæiske sprogfamilie?","o":["hindi og persisk","arabisk og hebraisk","litauisk og lettisk","græsk og albansk"],"a":"arabisk og hebraisk","r":"Arabisk og hebraisk er semitiske sprog. De andre par er indoeuropæiske, selvom nogle af dem tales langt fra Europa."},
{"l":9806,"g":9,"b":5,"role":"deep_challenge","insight":"perspective_shift","k":"f","variant":"authored","q":"Hvilken forfatter skrev romanen 'Rend mig i traditionerne' fra 1958?","o":["Peter Seeberg","Martin A. Hansen","Leif Panduro","Johannes V. Jensen"],"a":"Leif Panduro","r":"Leif Panduro gjorde oprør mod borgerlige normer med humor. Romanen blev en klassiker om ungdom i 1950'erne."},
{"l":9828,"g":9,"b":5,"role":"deep_challenge","insight":"perspective_shift","k":"t","variant":"authored","q":"Hvilken sætning er rigtig, når en forkortelse står lige før et komma?","o":["Vi købte lim, saks osv,. og så gik vi hjem.","Vi købte lim, saks osv, og så gik vi hjem.","Vi købte lim, saks, osv. og, så gik vi hjem.","Vi købte lim, saks osv., og så gik vi hjem."],"a":"Vi købte lim, saks osv., og så gik vi hjem.","r":"Forkortelsens punktum bliver stående, og kommaet kommer lige efter det."},
{"l":9850,"g":9,"b":5,"role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"authored","q":"Hvad er grundtanken i 'determinisme'?","o":["at alt, der sker, er bestemt af forudgående årsager","at mennesket har en fuldstændig fri vilje til alting","at det gode til sidst altid vil sejre over det onde","at viden kun kan opnås gennem streng selvdisciplin"],"a":"at alt, der sker, er bestemt af forudgående årsager","r":"Latin 'determinare' betyder at afgrænse. Hvis alt er bestemt på forhånd, rejser det spørgsmålet, om vi har en fri vilje."},
{"l":9872,"g":9,"b":5,"role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"authored","q":"Læs: 'Du kan ikke have ret i det med trafikken, for du kan ikke engang cykle.' Hvilken argumentationsfejl er det?","o":["cirkelslutning","ad hominem","falsk dilemma","glidebaneargument"],"a":"ad hominem","r":"Latin 'ad hominem' betyder 'mod personen'. Her angriber man modparten i stedet for påstanden om trafikken."},
{"l":9894,"g":9,"b":5,"role":"deep_challenge","insight":"perspective_shift","k":"f","variant":"authored","q":"Hvilken forfatter skrev morgen- og aftensange og den historiske roman 'Valdemar Seier'?","o":["Steen Steensen Blicher","Thomas Kingo","B.S. Ingemann","Jeppe Aakjær"],"a":"B.S. Ingemann","r":"B.S. Ingemann skrev historiske romaner fra middelalderen og sange, som stadig synges."},
{"l":9910,"g":9,"b":5,"role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"authored","q":"'Hun elsker at læse Blixen', siger Sara og mener Karen Blixens bøger. Hvilken figur bruger hun?","o":["metafor","anafor","ironi","metonymi"],"a":"metonymi","r":"Ved metonymi erstatter man et ord med et andet, der hører tæt sammen med det. Her står forfatteren for værket."},
{"l":9932,"g":9,"b":5,"role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"authored","q":"Hvad kendetegner en 'lapidarisk' stil?","o":["kort, fyndig og uden unødige ord","fyldt med lange, snørklede sætninger","overdrevent følelsesladet og sentimental","præget af mange lån fra fremmede sprog"],"a":"kort, fyndig og uden unødige ord","r":"Latin 'lapis' betyder sten. Stilen ligner en indskrift, der er hugget i sten, hvor hvert ord tæller."},
{"l":9950,"g":9,"b":5,"role":"deep_challenge","insight":"perspective_shift","k":"g","variant":"authored","q":"Indskriften på Guldhornet fra Gallehus er fra omkring år 400. Hvilket sprogtrin er den skrevet på?","o":["nydansk","urnordisk","gammeldansk","rigsdansk"],"a":"urnordisk","r":"Urnordisk er det sprog, der blev skrevet med den ældre futhark, før de nordiske sprog skiltes. Gammeldansk og nydansk er meget senere trin."},
{"l":9972,"g":9,"b":5,"role":"deep_challenge","insight":"perspective_shift","k":"g","variant":"authored","q":"Mathilde siger i klassen: 'Her er da koldt.' Hun mener, at vinduet skal lukkes. Hvad kaldes det?","o":["en direkte sproghandling","en metasproglig sætning","en indirekte sproghandling","en formel definition"],"a":"en indirekte sproghandling","r":"Sætningen ligner en konstatering, men er en opfordring. Når formen og hensigten er forskellige, er det en indirekte sproghandling."},
{"l":9994,"g":9,"b":5,"role":"deep_challenge","insight":"perspective_shift","k":"g","variant":"authored","q":"I 'god – bedre' og 'lille – små' bruger bøjningen to helt forskellige ordstammer. Hvad kaldes det?","o":["omlyd","aflyd","konversion","suppletion"],"a":"suppletion","r":"Ved suppletion hentes bøjningsformen fra en anden ordstamme. Det er ikke et vokalskifte, for 'bedre' er ikke dannet af 'god'."}
]$$::jsonb) AS e
JOIN (VALUES
  ('s', 'stavning', 'recall', 'factual', 'surface_association'),
  ('o', 'ordforråd', 'recall', 'factual', 'surface_association'),
  ('g', 'grammatik', 'application', 'applied', 'overgeneralization'),
  ('t', 'tegnsætning', 'application', 'applied', 'overgeneralization'),
  ('l', 'læseforståelse', 'comprehension', 'conceptual', 'surface_association'),
  ('f', 'litteratur', 'analysis', 'inferential', 'surface_association')
) AS m(k, concept, skill, dtype, mis) ON m.k = e->>'k';
